    "answer": "Skema Sertifikasi BNSP: Pengukuran Faktor Fisika Lingkungan Kerja (Kebisingan & Getaran) adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Teknisi.",
