    "description": "Rincian unit kompetensi SKKNI, persyaratan asesmen, bukti portofolio, dan sertifikasi BNSP untuk Pemeriksaan Saluran Udara & Kompresor Pernapasan.",
    "answer": "Skema Sertifikasi BNSP: Pemeriksaan Saluran Udara & Kompresor Pernapasan adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Teknisi.",
