    "metaTitle": "Skema Sertifikasi BNSP: Pengawasan Operasional Pengangkatan Beban Kritis (Lifting Supervisor) | Standar Kompetensi BNSP",
    "description": "Rincian unit kompetensi SKKNI, persyaratan asesmen, bukti portofolio, dan sertifikasi BNSP untuk Pengawasan Operasional Pengangkatan Beban Kritis (Lifting Supervisor).",
    "answer": "Skema Sertifikasi BNSP: Pengawasan Operasional Pengangkatan Beban Kritis (Lifting Supervisor) adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Officer & Pengawas.",
    "highlights": [
      "Standar Kompetensi Kerja Nasional (SKKNI)",
      "Sertifikat Kompetensi Garuda BNSP",
      "Uji Portofolio & Wawancara Asesor",
      "Diakui Industri Nasional & Regional"
    ],
    "blocks": [
      {
        "heading": "Deskripsi Skema Pengawasan Operasional Pengangkatan Beban Kritis (Lifting Supervisor)",
        "paragraphs": [
          "Skema sertifikasi ini disusun berdasarkan Standar Kompetensi Kerja Nasional Indonesia (SKKNI) guna memastikan tenaga kerja di Tingkat Officer & Pengawas memiliki pengetahuan, keterampilan, dan sikap kerja yang teruji.",
          "Uji kompetensi ini diselenggarakan oleh Lembaga Sertifikasi Profesi (LSP) pihak kedua atau ketiga yang telah mendapatkan lisensi resmi dari Badan Nasional Sertifikasi Profesi (BNSP)."
        ]
      },
      {
        "heading": "Unit Kompetensi yang Diujikan",
        "paragraphs": [
          "Asesi diwajibkan mendemonstrasikan penguasaan unit kompetensi inti dan pilihan yang tercantum dalam skema:"
        ],
        "bullets": [
          "Menerapkan Prosedur Keselamatan Kerja Terstandar",
          "Mengidentifikasi Potensi Bahaya & Pengendalian Risiko",
          "Mengelola Dokumentasi & Laporan Kerja Sesuai Standar",
          "Merespons Situasi Darurat di Tempat Kerja"
        ]
      },
      {
        "heading": "Persyaratan Asesmen & Portofolio",
        "paragraphs": [
          "Peserta uji kompetensi wajib melengkapi berkas administrasi meliputi ijazah, surat keterangan pengalaman kerja di bidang terkait, pas foto, serta bukti portofolio kerja aktual (seperti laporan inspeksi, JSA, atau SOP yang pernah disusun)."
        ]
      },
      {
        "heading": "Proses Uji Asesmen & Sertifikasi",
        "paragraphs": [
          "Proses asesmen meliputi verifikasi portofolio dokumen, tes tertulis/lisan, serta wawancara langsung oleh Asesor Kompetensi berlisensi BNSP untuk menyatakan asesi Kompeten (K)."
        ]
      }
    ],
    "faqs": [
      {
        "question": "Berapa lama masa berlaku sertifikat BNSP untuk skema ini?",
        "answer": "Sertifikat Kompetensi BNSP umumnya berlaku selama 3 (tiga) tahun dan dapat diperpanjang melalui proses resertifikasi / surveilans portofolio."
      },
      {
        "question": "Apakah sertifikasi BNSP ini dapat diikuti oleh individu umum?",
        "answer": "Ya, terbuka bagi peserta individu maupun utusan perusahaan yang memenuhi persyaratan bukti kerja dan pendidikan yang dipersyaratkan oleh skema."
      }
    ],
