    "description": "Rincian unit kompetensi SKKNI, persyaratan asesmen, bukti portofolio, dan sertifikasi BNSP untuk Pengawasan Keselamatan Bahan Berbahaya & Beracun (B3).",
    "answer": "Skema Sertifikasi BNSP: Pengawasan Keselamatan Bahan Berbahaya & Beracun (B3) adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Officer & Pengawas.",
