    "answer": "Skema Sertifikasi BNSP: Pemberian Umpan Balik Asesmen Konstruktif bagi Asesi adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Asesor & Instruktur.",
