    "answer": "Skema Sertifikasi BNSP: Audit Integrasi Sistem Manajemen K3, Lingkungan & Mutu (QEHS) adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Tingkat Auditor K3.",
