    "answer": "Skema Sertifikasi BNSP: Penerapan K3 Sektor Penerbangan & Fasilitas Bandara Udara adalah skema uji kompetensi profesi berstandar SKKNI yang diselenggarakan melalui LSP berlisensi BNSP untuk menguji keahlian Spesialis Sektoral.",
